- Naye abo abaliba mu ssanyu, baliba mu Jannati, gye baliba emirembe gyonna, nga eggulu n'ensi bwe biriba, okugyako nga Mukama wo bw'ayagala, ng'ekiweebwa ekitaggwaawo. 11:108
